const fs = require("fs");
const lines = fs.readFileSync("/reference/glossary.md", "utf8").split("\n");
for (const line of lines) {
  const parts = line.split("|").map(p => p.trim());
  if (parts.length >= 4) {
    const sym = parts[1];
    const kind = parts[2];
    if (["claim_relation", "link", "speech_act"].includes(kind)) {
      console.log(`${kind.padEnd(15)} ${sym.padEnd(30)} ${parts[3]}`);
    }
  }
}
'

